from dataclasses import dataclass
from typing import Union, List, Optional
from mashumaro.mixins.mashumaro_base import MashumaroBase
from mashumaro.types import Discriminator

@dataclass
class Base(MashumaroBase):
    type: str

@dataclass
class Sub1(Base):
    type: str = "sub1"

@dataclass
class Sub2(Base):
    type: str = "sub2"

def variant_tagger_fn(cls):
    if cls == Sub1:
        return ["sub1", "s1"]
    if cls == Sub2:
        return ["sub2", "s2"]
    return []

@dataclass
class Container(MashumaroBase):
    event: Union[Sub1, Sub2] = Discriminator(field="type", variant_tagger_fn=variant_tagger_fn, include_subtypes=True)

def test_discriminator_list():
    # This should work if the fix is applied
    try:
        c1 = Container.from_dict({"event": {"type": "sub1"}})
        assert isinstance(c1.event, Sub1)
        print("Test 1 passed: sub1 -> Sub1")

        c2 = Container.from_dict({"event": {"type": "s1"}})
        assert isinstance(c2.event, Sub1)
        print("Test 2 passed: s1 -> Sub1")

        c3 = Container.from_dict({"event": {"type": "sub2"}})
        assert isinstance(c3.event, Sub2)
        print("Test 3 passed: sub2 -> Sub2")

        c4 = Container.from_dict({"event": {"type": "s2"}})
        assert isinstance(c4.event, Sub2)
        print("Test 4 passed: s2 -> Sub2")
    except Exception as e:
        print(f"Test failed: {e}")
        import traceback
        traceback.print_exc()

if __name__ == "__main__":
    test_discriminator_list()
